ui = '''
const M=LayoutPrototype,S=LayoutScenarios;
let index=0,position=0,state=M.seed();
const $=id=>document.getElementById(id);
function textList(id,rows){$(id).replaceChildren(...rows.map(row=>{const li=document.createElement('li');li.textContent=row;return li;}));}
function render(){
  const c=S.cases[index],p=M.project(state);
  $('scenario-title').textContent=c.title;$('description').textContent=c.description;$('note').textContent=state.note;
  document.querySelectorAll('[role=tab]').forEach((b,i)=>b.setAttribute('aria-selected',String(index===i)));
  textList('items',Object.values(p.entities).filter(e=>e.fields.type!=='account').map(e=>e.fields.name+' · '+e.id+' · '+(e.deleted?'Deleted':p.repaired[e.id]?'Recovered work':e.fields.type)));
  textList('processes',state.runtimes.map(r=>r.id+' on '+r.server+' · '+r.incarnation+' · '+(r.live?'Running':'Terminated')+' · '+(M.canAttach(state,r.id)?'Attachment ready':'Attachment blocked')));
  textList('cleanup',state.outbox.length?state.outbox.map(q=>q.target+' · '+q.stage+' · '+q.operation):['No close intent recorded']);
  $('summary').textContent='Model day '+state.day+' · '+state.ops.length+' durable operations · '+state.pending.length+' buffered operations · '+state.receipts.length+' runtime receipts · '+(state.confirmation?'Confirmation required':'No confirmation pending');
  $('next').disabled=position>=c.steps.length;$('next').textContent=position<c.steps.length?c.steps[position].label:'Walkthrough complete';
  $('step-status').textContent=position<c.steps.length?'Step '+(position+1)+' of '+c.steps.length:'Walkthrough complete';
  $('diagnostics').textContent=p.history.length+' recoverable edit(s) · '+state.rejected.length+' rejected operation(s) · Mac selection: '+(state.selection.mac||'none')+' · Phone selection: '+(state.selection.phone||'none');
  $('raw').textContent=JSON.stringify({recoverable:p.history,structuralRepair:p.repaired,rejected:state.rejected,channel:state.channel,connections:state.connections,pending:state.pending,recoveryQuarantine:state.rejected,checkpoint:M.compact(state)},null,2);
}
function choose(i){index=i;position=0;state=M.seed();render();}
S.cases.forEach((c,i)=>{const b=document.createElement('button');b.setAttribute('role','tab');b.textContent=c.title;b.onclick=()=>choose(i);$('tabs').append(b);});
$('next').onclick=()=>{const step=S.cases[index].steps[position];if(step){state=step.run(state);position++;render();}};
$('reset').onclick=()=>choose(index);
for(const [label,fn]of [['Concurrent rename',S.concurrent],['Disconnect',S.offline],['Close workspace',s=>M.close(s,'workspace')],['Confirm close',s=>M.close(s,'workspace',true)],['Cancel confirmation',s=>{s=M.copy(s);s.confirmation=false;s.note='Cancelled: the layout and runtime remain unchanged.';return s;}],['Relay accepts',s=>M.submit(s)],['Delivery fails',s=>M.submit(s,false)],['Pass eight days',M.advance],['Restart client',M.restart],['Reconnect and reconcile',s=>M.reconcile(S.online(s))]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{state=fn(state);render();};$('free').append(b);}
window.prototypeState=()=>M.copy(state);
render();
'''
page=shell+'<script>\n'+(root/'model.js').read_text()+'\n'+(root/'scenarios.js').read_text()+'\n'+ui+'\n</script>\n'
(root/'candidate.html').write_text(page)
